def get_values(a, m):
    values = [(0, 1)]
    for v in a:
        new_values1, new_values2 = [], []
        for (x, y) in values:
            x1, y1 = x + v, y + v
            if x1 < m:
                if y1 < m:
                    new_values1.append((x1, y1))
                else:
                    print(m - 1)
                    raise Solved
            else:
                new_values2.append((x1 - m, y1 - m))

        new_values = []
        hx, hy = 0, 1
        for pair in merge(values, new_values1, new_values2):
            if hy >= pair[0]:
                hy = pair[1]
            else:
                new_values.append((hx, hy))
                hx, hy = pair
