        ni = len(Ki)
        mi = len(Ki[0])
        Si = [[None] * mi for _ in range(ni)]
        for j in range(ni):
            Si[j][mi-1] = Ki[j][mi-1]
            for k in reversed(range(mi-1)):
                Si[j][k] = (Ki[j][k] + Si[j][k+1]) % M
        for j in range(1, ni):
            for k in range(mi):
                Si[j][k] += Si[j-1][k]
