def binarySearch(arr, n, key):
    left = 0
    right = n-1
    mid = 0
    res = n
    while (left <= right):
        mid = (right + left)//2
        if (arr[mid] >= key):
            res=mid
            right = mid-1
        else:
            left = mid + 1
    return res

