            for j in xrange(k + 1):
                for y, t in res[j].viewitems():
                    if j and x <= 18 and factorial(x) + y <= s:
                        nr[j-1][factorial(x) + y] += t
                    if x + y <= s:
                        nr[j][x + y] += t
