            res = nr
        return res
    def g(b):
        res = [defaultdict(int) for _ in xrange(k + 1)]
        res[k][s] = 1
        for x in b:
            nr = [defaultdict(int) for _ in xrange(k + 1)]
            for j in xrange(k + 1):
                for y, t in res[j].viewitems():
                    if j and x <= 18 and y - factorial(x) >= 0:
                        nr[j-1][y - factorial(x)] += t
                    if y - x >= 0:
                        nr[j][y - x] += t
                    nr[j][y] += t
            res = nr
        return res
